  @spec two_sum(nums :: [integer], target :: integer) :: [integer]
  def two_sum(nums, target) do
    Enum.find_value(0..(length(nums) - 2), fn i ->
      Enum.find_value((i + 1)..(length(nums) - 1), fn j ->
        if Enum.at(nums, i) + Enum.at(nums, j) == target, do: [i, j]
